from math import gcd
from collections import Counter
from pathlib import Path

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    rare={c for c,n in counts.items() if n<=max(10,(h*w)//100)}
    coords=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v in rare]
    if not coords:
        return [row[:] for row in grid]
    ys=sorted({r for r,c in coords}); xs=sorted({c for r,c in coords})
    sy=0; sx=0
    for a,b in zip(ys,ys[1:]): sy=gcd(sy,b-a)
    for a,b in zip(xs,xs[1:]): sx=gcd(sx,b-a)
    if not sy or not sx: raise ValueError((ys,xs))
    y0,y1=ys[0],ys[-1]; x0,x1=xs[0],xs[-1]
    samples=[grid[y0+i*sy+sy//2][x0+j*sx+sx//2] for i in range((y1-y0)//sy) for j in range((x1-x0)//sx)]
    fill=Counter(samples).most_common(1)[0][0]
    out=[]
    for i in range((y1-y0)//sy):
        row=[]
        for j in range((x1-x0)//sx):
            corners=(grid[y0+i*sy][x0+j*sx],grid[y0+i*sy][x0+(j+1)*sx],grid[y0+(i+1)*sy][x0+j*sx],grid[y0+(i+1)*sy][x0+(j+1)*sx])
            row.append(corners[0] if corners[0] in rare and all(v==corners[0] for v in corners) else fill)
        out.append(row)
    return out

